contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking an amount to deposit
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read balance of contract before deposit
        uint beforeBalance = address(c).balance;

        // perform deposit of `amount`
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // read balance after deposit
        uint afterBalance = address(c).balance;

        // Try to detect whether the contract would allow withdrawAll to succeed for this depositor:
        // We'll call withdrawAll in a try/catch to see if it reverts. We must not change c state inside require/assert, so we perform the call and capture revert flag.
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule (single assert):
        // 1) The observable balance of c increased by exactly amount due to deposit.
        // 2) If withdrawAll would revert now, that's allowed; otherwise (it does not revert) then after the withdraw the contract's balance must be <= afterBalance (i.e., withdraw cannot increase c's balance).
        // We express both as a single boolean assertion combining them.
        assert(afterBalance == beforeBalance + amount && (reverted || address(c).balance <= afterBalance));
    }

    // accept Ether for withdrawAll callback
    receive() external payable { }
}

